# -*- coding: utf-8 -*-
"""Root fillet generated by a pinion-type shaper cutter (spur, external gears).

The model follows the generating principle described by Lian (2006): the
shaper cutter is treated as a gear that meshes with the work gear without
backlash.  The tip round of the cutter (radius ``rho0``) is tangent to the
cutter's outside circle and to its involute flank.  While the two "gears"
roll, the centre of the tip round traces a trochoid in the work-gear frame
and the root fillet is the envelope of the tip round, i.e. the parallel curve
of that trochoid at distance ``rho0``.

Everything is computed in a single length unit (millimetres in FGPG), in the
transverse plane, using the same angular conventions as
:mod:`fine_gear_profile_generator.core.geometry_generator`:

* the work-gear tooth *space* centre line lies on the +x axis,
* "flank 1" is the flank on the +y side of that space,
* the polar angle of flank 1 on the base circle is ``flank_base_angle`` and
  at radius ``r`` it is ``flank_base_angle + inv(arccos(rb / r))``.

Cutter layout at the reference position (gear rotation ``theta = 0``): the
cutter centre is at ``(C, 0)`` and one cutter tooth points at the gear centre.

Protuberance ``delta0`` is modelled as an outward normal offset of the cutter
flank in the tip region: the tip round is made tangent to an involute that is
offset by ``delta0`` from the nominal flank.  With ``delta0 > 0`` the fillet
deliberately undercuts the involute (pre-grind / pre-shave relief).
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np
from scipy.optimize import brentq

_J = np.array([[0.0, -1.0], [1.0, 0.0]])  # +90 degree rotation


def _inv(angle):
    """Involute function ``tan(a) - a``."""
    return np.tan(angle) - angle


def _rot(angle: float) -> np.ndarray:
    c, s = np.cos(angle), np.sin(angle)
    return np.array([[c, -s], [s, c]])


def _inv_inverse(value: float) -> float:
    """Return the angle ``a`` in ``(0, pi/2)`` with ``inv(a) == value``."""
    if value <= 0.0:
        raise ValueError("Operating pressure angle would be non-positive; "
                         "check tooth thickness and cutter parameters.")
    return float(brentq(lambda a: _inv(a) - value, 1e-9, np.pi / 2 - 1e-9, xtol=1e-15))


@dataclass
class ShaperFilletResult:
    """Fillet generated by a shaper cutter on flank 1 of the work gear.

    Attributes:
        points: ``(N, 2)`` array ordered from the root circle to the end of the
            fillet (start of involute or its intersection with the involute).
        root_radius: Radius of the root circle cut by the cutter.
        root_angle: Polar angle of ``points[0]`` (end of the root arc).
        soi_radius: Radius of the last fillet point (start of involute, SOI).
        tangent_to_involute: ``True`` when the fillet joins the involute
            tangentially (no undercut), ``False`` when it intersects it.
        center_distance: Generating centre distance between gear and cutter.
        operating_pressure_angle: Generating pressure angle in radians.
        cutter_outside_radius: Outside radius of the cutter used.
    """

    points: np.ndarray
    root_radius: float
    root_angle: float
    soi_radius: float
    tangent_to_involute: bool
    center_distance: float
    operating_pressure_angle: float
    cutter_outside_radius: float


class _Kinematics:
    """Position of the cutter tip-round centre in the work-gear frame."""

    def __init__(self, center_distance, ratio, tip_center):
        self.C = center_distance
        self.ratio = ratio  # d(theta0)/d(theta) = -z / n0
        self.s = tip_center  # tip-round centre in the cutter frame

    def center(self, theta):
        theta0 = self.ratio * theta
        fixed = np.array([self.C, 0.0]) + _rot(theta0) @ self.s
        return _rot(-theta) @ fixed

    def velocity(self, theta):
        theta0 = self.ratio * theta
        fixed = np.array([self.C, 0.0]) + _rot(theta0) @ self.s
        d_fixed = self.ratio * (_J @ (_rot(theta0) @ self.s))
        return -_J @ (_rot(-theta) @ fixed) + _rot(-theta) @ d_fixed

    def to_cutter_frame(self, theta, vector):
        """Express a work-gear-frame direction in the cutter frame."""
        return _rot(-self.ratio * theta) @ (_rot(theta) @ vector)


def generate_shaper_fillet(
    module: float,
    teeth: int,
    pressure_angle_rad: float,
    flank_base_angle: float,
    root_radius: float,
    cutter_teeth: int,
    tip_radius: float,
    protuberance: float = 0.0,
    cutter_profile_shift: float = 0.0,
    samples: int = 30,
) -> ShaperFilletResult:
    """Generate the root fillet of flank 1 cut by a shaper cutter.

    Args:
        module: Module (length unit of the result).
        teeth: Number of teeth of the (external) work gear, ``> 0``.
        pressure_angle_rad: Reference pressure angle shared by gear and cutter.
        flank_base_angle: Polar angle of flank 1 on the base circle
            (``involute_start_angle`` of :func:`gear_math.calculate_gear_parameters`).
            It already contains profile shift and backlash.
        root_radius: Root radius to be cut.  The cutter outside radius is
            chosen so that the cutter reaches exactly this radius.
        cutter_teeth: Number of teeth of the cutter, ``n0``.
        tip_radius: Tip-round radius of the cutter, ``rho0``.
        protuberance: Protuberance ``delta0`` (normal offset of the flank at
            the tip), ``0`` for a plain cutter.
        cutter_profile_shift: Profile shift coefficient of the cutter.
        samples: Number of points of the returned fillet polyline.

    Returns:
        A :class:`ShaperFilletResult`.

    Raises:
        ValueError: If the cutter geometry is not feasible.
    """

    if teeth <= 0:
        raise ValueError("The shaper-cutter fillet is implemented for external gears only.")
    if cutter_teeth < 5:
        raise ValueError("Shaper cutter must have at least 5 teeth.")
    if tip_radius < 0 or protuberance < 0:
        raise ValueError("Tip radius and protuberance must be non-negative.")
    if protuberance > tip_radius and tip_radius > 0:
        raise ValueError("Protuberance must not exceed the tip radius.")

    m, z, n0 = float(module), int(teeth), int(cutter_teeth)
    alpha = float(pressure_angle_rad)
    rho = float(tip_radius)

    rb = 0.5 * m * z * np.cos(alpha)
    r0 = 0.5 * m * n0
    rb0 = r0 * np.cos(alpha)

    # Half tooth angle of the cutter on its base circle.
    cutter_half_base = (np.pi / 2 + 2 * cutter_profile_shift * np.tan(alpha)) / n0 + _inv(alpha)

    # Zero-backlash mesh: space of the gear == tooth of the cutter on the
    # operating pitch circles  ->  closed form for inv(alpha_w).
    alpha_w = _inv_inverse((n0 * cutter_half_base - z * flank_base_angle) / (z + n0))
    C = (rb + rb0) / np.cos(alpha_w)

    ra0 = C - root_radius
    rs0 = ra0 - rho
    if rs0 <= rb0:
        raise ValueError(
            "Cutter tip-round centre lies inside the cutter base circle "
            f"(r_s0={rs0:.4f} <= rb0={rb0:.4f}); increase the cutter teeth or reduce the tip radius."
        )

    # Angle of the tip-round centre from the cutter tooth axis: the centre lies
    # on the cutter flank involute offset inwards by (rho - delta0); an
    # involute offset by d along its normal is the same involute rotated by d/rb0.
    gamma = cutter_half_base - _inv(np.arccos(rb0 / rs0)) - (rho - protuberance) / rb0
    if gamma < 0:
        raise ValueError(
            "Cutter tip round does not fit on the cutter tooth (tooth too pointed); "
            "reduce the tip radius or the dedendum."
        )

    # Cutter tooth axis points to -x (angle pi); flank 1 side is +y.
    s = rs0 * np.array([np.cos(np.pi - gamma), np.sin(np.pi - gamma)])

    # Direction (cutter frame) from the tip-round centre to the flank tangency
    # point: the involute normal through S is tangent to the base circle.
    flank_dir = _flank_tangency_direction(s, rb0, cutter_half_base, protuberance, rho)
    od_dir = s / np.linalg.norm(s)

    kin = _Kinematics(C, -z / n0, s)

    # Gear rotation at which the tip-round centre is deepest (cutter rotated by +gamma).
    theta_deep = -(n0 / z) * gamma

    def envelope(theta):
        c = kin.center(theta)
        t = kin.velocity(theta)
        n = _J @ t
        n /= np.linalg.norm(n)
        return c, n

    c_d, n_d = envelope(theta_deep)
    sigma = -np.sign(np.dot(n_d, c_d))  # pick the branch facing the gear centre

    def contact(theta):
        c, n = envelope(theta)
        return c + sigma * rho * n, sigma * n

    def arc_position(theta):
        """Signed angle of the contact direction measured from od_dir towards flank_dir."""
        _, w = contact(theta)
        w0 = kin.to_cutter_frame(theta, w)
        return np.arctan2(_cross(od_dir, w0), np.dot(od_dir, w0))

    arc_end = np.arctan2(_cross(od_dir, flank_dir), np.dot(od_dir, flank_dir))

    # Direction of the sweep that moves the contact point towards the flank.
    step = 1e-4
    direction = 1.0 if np.sign(arc_position(theta_deep + step)) == np.sign(arc_end) else -1.0

    if rho == 0.0:
        theta_end = theta_deep
    else:
        # March until the contact point passes the flank tangency, then refine.
        delta = direction * 0.01 / max(z, 1)
        t_prev, t_cur = theta_deep, theta_deep + delta
        for _ in range(100000):
            if abs(arc_position(t_cur)) >= abs(arc_end):
                break
            t_prev, t_cur = t_cur, t_cur + delta
        else:  # pragma: no cover - defensive
            raise RuntimeError("Could not locate the end of the shaper fillet.")
        theta_end = brentq(lambda t: abs(arc_position(t)) - abs(arc_end), t_prev, t_cur, xtol=1e-14)

    # Signed distance (arc length) of a fillet point from the generated involute
    # of flank 1: > 0 means the fillet cuts into the involute (undercut or
    # protuberance relief).  Below the base circle no involute exists, so the
    # fillet is the profile there (treated as > 0).
    def gap(theta):
        p = contact(theta)[0]
        r = np.hypot(*p)
        if r < rb:
            return 1.0
        return (np.arctan2(p[1], p[0]) - flank_base_angle - _inv(np.arccos(rb / r))) * r

    tangent = True
    tol = 1e-7 * m
    probe = np.linspace(theta_deep, theta_end, 400)
    probe_gap = np.array([gap(t) for t in probe])
    probe_r = np.array([np.hypot(*contact(t)[0]) for t in probe])
    cutting = np.where((probe_r >= rb) & (probe_gap > tol))[0]
    if gap(theta_end) <= tol and cutting.size:
        # Classic undercut: the fillet cuts into the involute above the base
        # circle and leaves it again before the flank takes over.  The profile
        # follows the fillet up to that last crossing, then the involute.
        tangent = False
        k = int(cutting[-1])
        theta_end = brentq(gap, probe[k], probe[k + 1], xtol=1e-14)
    elif gap(theta_end) > tol:
        # The tip round cuts into the involute.  The cutter body contains the
        # whole tip circle, so the profile follows the envelope of that circle
        # until it re-crosses the involute (same treatment as the rack method).
        tangent = False
        delta = direction * 0.002 / max(z, 1)
        t_prev, t_cur = theta_end, theta_end + delta
        for _ in range(100000):
            if gap(t_cur) <= 0.0:
                break
            t_prev, t_cur = t_cur, t_cur + delta
        else:  # pragma: no cover - defensive
            raise RuntimeError("Shaper fillet does not intersect the involute.")
        theta_end = brentq(gap, t_prev, t_cur, xtol=1e-14)

    thetas = np.linspace(theta_deep, theta_end, max(int(samples), 2))
    points = np.array([contact(t)[0] for t in thetas])

    root_angle = float(np.arctan2(points[0, 1], points[0, 0]))
    soi_radius = float(np.hypot(*points[-1]))
    return ShaperFilletResult(
        points=points,
        root_radius=float(root_radius),
        root_angle=root_angle,
        soi_radius=soi_radius,
        tangent_to_involute=tangent,
        center_distance=float(C),
        operating_pressure_angle=float(alpha_w),
        cutter_outside_radius=float(ra0),
    )


def _cross(u, v):
    return u[0] * v[1] - u[1] * v[0]


def _flank_tangency_direction(s, rb0, cutter_half_base, protuberance, rho):
    """Unit vector (cutter frame) from the tip-round centre to its flank tangency point."""
    r = np.linalg.norm(s)
    phi_s = np.arctan2(s[1], s[0])
    beta = np.arccos(rb0 / r)
    best, best_err = None, np.inf
    for foot in (phi_s + beta, phi_s - beta):
        f = rb0 * np.array([np.cos(foot), np.sin(foot)])
        u = (s - f) / np.linalg.norm(s - f)
        for sign in (1.0, -1.0):
            if rho == 0:
                return s / r
            t = s + sign * rho * u
            rt = np.linalg.norm(t)
            if rt <= rb0:
                continue
            # Point must lie on the (offset) flank: angle from tooth axis == psi(r).
            psi = cutter_half_base - _inv(np.arccos(rb0 / rt)) + protuberance / rb0
            ang_from_axis = np.pi - np.arctan2(t[1], t[0])
            err = abs(ang_from_axis - psi)
            if err < best_err:
                best, best_err = sign * u, err
    return best
